import { revalidateTag } from 'next/cache'
import { getProducts, PRODUCTS_CACHE_TAG } from '@/lib/products'

export default async function Page() {
  async function syncCatalog() {
    'use server'

    // Stale-while-revalidate: the admin keeps seeing the current list right
    // away, and every view tagged "products" refreshes in the background on
    // its next request instead of blocking on a full catalog recompute.
    revalidateTag(PRODUCTS_CACHE_TAG, 'max')
  }

  const products = await getProducts()

  return (
    <main>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <p>{products.length} products</p>

      <table>
